import json, re

def parse_packages(filename):
    with open(filename) as f:
        # dotnet package list --format json may output multiple JSON objects; take the last complete one
        content = f.read()
    # Find all JSON objects
    objs = []
    decoder = json.JSONDecoder()
    idx = 0
    while idx < len(content):
        content_stripped = content[idx:].lstrip()
        if not content_stripped:
            break
        idx = len(content) - len(content_stripped)
        try:
            obj, end = decoder.raw_decode(content, idx)
            objs.append(obj)
            idx += end
        except json.JSONDecodeError:
            idx += 1
    data = objs[-1] if objs else {}
    result = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = {'requested': pkg.get('requestedVersion',''), 'resolved': pkg.get('resolvedVersion','')}
        result[pname] = pkgs
    return result

baseline = parse_packages('baseline-packages.json')
after = parse_packages('after-cpm-packages.json')

