    ap = after.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, {}).get('resolved', 'MISSING')
        av = ap.get(pkg, {}).get('resolved', 'MISSING')
        if bv != av:
            print(f'  {proj}: {pkg} {bv} -> {av}')
